INSERT INTO public.templates (id, name, description, domain, category, is_global, content) VALUES
(gen_random_uuid(), 'Notify Assignee When Task Becomes Overdue', 'Automatically sends a notification to the task assignee when a task becomes overdue.', 'Automations', 'Automation', true, '{"trigger_type":"task.overdue","trigger_config":{},"conditions":{"operator":"AND","rules":[]},"actions":[{"id":"action-1","type":"notify.user","config":{"message":"Your task is now overdue."}}]}'),
(gen_random_uuid(), 'Notify Owner About High-Priority Overdue Work', 'Sends a notification when a high-priority task is overdue.', 'Automations', 'Automation', true, '{"trigger_type":"task.overdue","trigger_config":{},"conditions":{"operator":"AND","rules":[{"field":"task.priority","operator":"equals","value":"High"}]},"actions":[{"id":"action-1","type":"notify.user","config":{"message":"High priority task is overdue!"}}]}'),
(gen_random_uuid(), 'Assign Newly Created Task', 'Assigns newly created tasks in a specific project to a designated team member.', 'Automations', 'Automation', true, '{"trigger_type":"task.created","trigger_config":{},"conditions":{"operator":"AND","rules":[]},"actions":[{"id":"action-1","type":"task.assign","config":{"userId":""}}]}'),
(gen_random_uuid(), 'Create Task After Request Approval', 'Automatically spins up a new task when a request gets approved.', 'Automations', 'Automation', true, '{"trigger_type":"request.approved","trigger_config":{},"conditions":{"operator":"AND","rules":[]},"actions":[{"id":"action-1","type":"task.create","config":{"title":"Fulfill approved request","projectId":""}}]}'),
(gen_random_uuid(), 'Notify Requester After Approval', 'Sends a notification to the requester when their request is approved.', 'Automations', 'Automation', true, '{"trigger_type":"request.status_changed","trigger_config":{"targetStatus":"Approved"},"conditions":{"operator":"AND","rules":[]},"actions":[{"id":"action-1","type":"notify.user","config":{"message":"Your request has been approved!"}}]}');
